import {BUILDING_DETAILS,detailFitsSurface,placeSurfaceDetails} from './building-surface-details.js?v=shaped-details-1';
import {connectedBuildingSurfaces} from './building-surface-fill.js?v=shaped-details-1';
import {floorPaintKey,floorSurfaceMaterial,paintFloorSurfaces,surfaceLevel} from './building-floor-paint.js?v=shaped-details-1';
import {projectedBuildingSurfaces,pickBuildingSurface,paintPickedSurfaces} from './building-surface-picking.js?v=shaped-details-1';
import {BUILDING_MATERIALS,SURFACE_NAMES} from './building-materials.js?v=shaped-details-1';
export function mountBuildingPreviewPaint(canvas,{get,camera,apply,applyFloor,applyDetails,detail,render,mode,material,status,scope}){
 const base=Object.fromEntries(['onpointerdown','onpointermove','onpointerup','onpointercancel','onkeydown','onwheel'].map(k=>[k,canvas[k]]));let hover=null,stroke=null,geometry=null;
 const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};
 function surfaces(){const d=get(),key=[d.blocks,d.voxels,d.footprint,d.rotation,d.blockGeometry];if(!geometry||key.some((v,i)=>v!==geometry.key[i]))geometry={key,faces:projectedBuildingSurfaces(d,d.rotation)};return geometry.faces;}
 const perFloor=()=>mode.value==='detail'||mode.value==='fill'||scope?.value==='floor',key=face=>perFloor()?floorPaintKey(face):face.index*5+face.side,paint=faces=>mode.value==='detail'?applyDetails(placeSurfaceDetails(get(),faces,Number(detail.value))):scope||mode.value==='fill'?applyFloor(paintFloorSurfaces(get(),perFloor()?faces:faces.flatMap(face=>Array.from({length:24},(_,level)=>({...face,from:level,to:level+1}))),Number(material.value))):apply(paintPickedSurfaces(get().materials,faces,Number(material.value)));
 const selection=face=>!face||mode.value==='detail'&&!detailFitsSurface(Number(detail.value),face)?[]:mode.value==='fill'?connectedBuildingSurfaces(get(),surfaces(),face):[face];
 const pick=p=>pickBuildingSurface(surfaces(),p,camera());
 function message(face){if(face&&mode.value==='detail'){status.textContent=detailFitsSurface(Number(detail.value),face)?`${BUILDING_DETAILS[Number(detail.value)]} · ${SURFACE_NAMES[face.side]} · floor ${surfaceLevel(face)+1}. Paint beneath the detail stays unchanged.`:'Choose a wall for this detail. Roofs accept vent grilles.';return;}if(face&&mode.value==='fill'){status.textContent=`${selection(face).length} connected ${SURFACE_NAMES[face.side].toLowerCase()} tiles with the same material. Click or press Enter to fill this plane.`;return;}status.textContent=face?`${SURFACE_NAMES[face.side]} · column ${face.x+1}, row ${face.y+1}. ${perFloor()?`Floor ${surfaceLevel(face)+1}. Paint applies only to this surface tile.`:'Paint applies to this column and side across its layers.'}`:'Point at a visible model surface. Choose a block layout or independent layers before painting.';}
 function act(face){if(!face){message(null);return;}if(mode.value==='sample'){material.value=String(floorSurfaceMaterial(get(),face));status.textContent=`Selected ${BUILDING_MATERIALS[Number(material.value)]}. The building is unchanged.`;}else{paint(selection(face));message(face);}}
 function cancel(){stroke=null;render();}
 mode.onchange=()=>{stroke=null;hover=null;base.onpointercancel?.();canvas.style.cursor=mode.value==='pan'?'grab':'crosshair';if(scope)scope.disabled=mode.value==='fill'||mode.value==='detail';if(detail)detail.disabled=mode.value!=='detail';material.disabled=mode.value==='detail';render();};material.onchange=cancel;if(detail)detail.onchange=cancel;if(scope)scope.onchange=cancel;
 canvas.onpointerdown=e=>{if(mode.value==='pan')return base.onpointerdown?.(e);if(e.button!==0)return;e.preventDefault();canvas.focus({preventScroll:true});hover=point(e);const face=pick(hover);if(mode.value==='sample'){act(face);render();return;}const d=get();stroke={id:e.pointerId,surfaceDetails:d.surfaceDetails,surfacePaint:d.surfacePaint,materials:d.materials,blocks:d.blocks,voxels:d.voxels,footprint:d.footprint,rotation:d.rotation,camera:JSON.stringify(camera()),faces:new Map()};for(const f of selection(face))stroke.faces.set(key(f),f);canvas.setPointerCapture(e.pointerId);message(face);render();};
 canvas.onpointermove=e=>{if(mode.value==='pan')return base.onpointermove?.(e);hover=point(e);const face=pick(hover);if(mode.value!=='fill'&&stroke?.id===e.pointerId)for(const f of selection(face))stroke.faces.set(key(f),f);message(face);render();};
 canvas.onpointerup=e=>{if(mode.value==='pan')return base.onpointerup?.(e);if(stroke?.id!==e.pointerId)return;const current=stroke;stroke=null;const d=get();if(!e.shiftKey&&d.surfaceDetails===current.surfaceDetails&&d.surfacePaint===current.surfacePaint&&d.materials===current.materials&&d.blocks===current.blocks&&d.voxels===current.voxels&&d.footprint===current.footprint&&d.rotation===current.rotation&&JSON.stringify(camera())===current.camera&&current.faces.size)paint([...current.faces.values()]);render();};
 canvas.onpointercancel=e=>{if(mode.value==='pan')return base.onpointercancel?.(e);cancel();};
 canvas.onwheel=e=>{stroke=null;base.onwheel?.(e);};
 canvas.onkeydown=e=>{if(mode.value!=='pan'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter',' '].includes(e.key)){e.preventDefault();e.stopPropagation();stroke=null;hover??={x:128,y:300};const step=e.shiftKey?24:8;if(e.key==='ArrowLeft')hover.x-=step;if(e.key==='ArrowRight')hover.x+=step;if(e.key==='ArrowUp')hover.y-=step;if(e.key==='ArrowDown')hover.y+=step;if(e.key==='Enter'||e.key===' ')act(pick(hover));else message(pick(hover));render();return;}if(e.key==='Escape'&&stroke){e.preventDefault();e.stopPropagation();cancel();return;}stroke=null;base.onkeydown?.(e);};
 return{reset(){stroke=null;hover=null;geometry=null;},draw(ctx){if(mode.value==='pan')return;canvas.style.cursor='crosshair';const face=hover?pick(hover):null;const selected=new Set(stroke?[...stroke.faces.keys()]:selection(face).map(key));ctx.save();ctx.strokeStyle='#ffe180';ctx.lineWidth=1.2/camera().zoom;for(const f of surfaces())if(selected.has(key(f))){ctx.beginPath();f.polygon.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.stroke();}if(hover){const c=camera(),x=(hover.x-c.x)/c.zoom,y=(hover.y-c.y)/c.zoom;ctx.beginPath();ctx.moveTo(x-3/c.zoom,y);ctx.lineTo(x+3/c.zoom,y);ctx.moveTo(x,y-3/c.zoom);ctx.lineTo(x,y+3/c.zoom);ctx.stroke();}ctx.restore();}};
}
